// Node: "Normalize Form Response" — Code node, mode: Run Once for Each Item
// One row of the Google Form's response sheet → { intake_id, channel, received_at, raw_text, submitted_by, file_id }.
// Column names are the Form's question titles. They are matched loosely (case-insensitive, and the timestamp
// column may be "Timestamp" or "Marca temporal" depending on the account's language), so a renamed question
// does not silently break the intake.

const row = $json;
const keys = Object.keys(row);
const find = (re) => keys.find((k) => re.test(k));

const tsKey = find(/timestamp|marca temporal|fecha/i) || keys[0];
const channelKey = find(/^channel$|canal/i);
const textKey = find(/intake text|texto/i);
const nameKey = find(/your name|nombre/i);
const fileKey = find(/intake file|archivo|file/i);

const timestamp = String(row[tsKey] ?? '').trim();
const channel = String((channelKey && row[channelKey]) || 'other').trim();
const pasted = String((textKey && row[textKey]) || '').trim();
const submitted_by = String((nameKey && row[nameKey]) || '').trim() || 'not provided';

// A file-upload answer is one or more Google Drive links: https://drive.google.com/open?id=<FILE_ID>
const fileAnswer = String((fileKey && row[fileKey]) || '');
const fileMatch = fileAnswer.includes('drive.google.com') ? fileAnswer.match(/[-\w]{25,}/) : null;
const file_id = fileMatch ? fileMatch[0] : '';

if (!pasted && !file_id) {
  throw new Error(`Form response at ${timestamp || 'unknown time'} has neither intake text nor an uploaded file. Nothing to process.`);
}

// Stable id per form response so re-polling the same row updates the sheet row instead of duplicating it.
const intake_id = `gform-${timestamp.replace(/\D/g, '') || Date.now()}`;
const parsed = new Date(timestamp);
const received_at = Number.isNaN(parsed.getTime()) ? timestamp : parsed.toISOString();

return { json: { intake_id, channel, received_at, raw_text: pasted, submitted_by, file_id } };

// Node: "Attach File Text" — Code node, mode: Run Once for Each Item
// After "Read Downloaded File" put the uploaded file's contents in $json.data, merge it into raw_text.
// Pasted text wins when both were provided; the file is the fallback. Drops the transport fields.

// Belt and braces: if the Drive/Extract nodes dropped the JSON (Extract From File does so unless
// "Keep Source" is explicitly set), recover the intake fields from the node that built them.
let origin = {};
try { origin = $('Normalize Form Response').item.json || {}; } catch (e) { origin = {}; }
const j = { ...origin, ...$json };
const pasted = String(j.raw_text ?? '').trim();
const fromFile = String(j.data ?? '').trim();
const raw_text = pasted || fromFile;

if (!raw_text) {
  throw new Error(`Uploaded file for ${j.intake_id} is empty or could not be read as text.`);
}

return {
  json: {
    intake_id: j.intake_id,
    channel: j.channel,
    received_at: j.received_at,
    raw_text,
    submitted_by: j.submitted_by,
  },
};

// Node: "Normalize Form Intake" — Code node, mode: Run Once for Each Item
// Turns a submission of the "New intake" form into the same shape the batch path produces:
//   { intake_id, channel, received_at, raw_text }
// The form offers two ways in: paste the text, or upload a file (.txt/.json/.eml/.md). If a file was
// uploaded, "Read Uploaded File" has already put its contents in $json.data. Pasted text wins if both exist.

// If the file was read by "Read Uploaded File", that node may have dropped the form fields; recover them.
let origin = {};
try { origin = $('Intake Form').item.json || {}; } catch (e) { origin = {}; }
const j = { ...origin, ...$json };
const pasted = String(j['Intake text'] ?? '').trim();
const fromFile = String(j.data ?? '').trim();
const raw_text = pasted || fromFile;

if (!raw_text) {
  throw new Error('The form was submitted with neither pasted text nor a file. Nothing to process.');
}

const now = new Date();
const stamp = now.toISOString().replace(/[-:]/g, '').replace(/\..+$/, ''); // e.g. 20260915T170521

return {
  json: {
    intake_id: `form-${stamp}`,
    channel: String(j['Channel'] ?? 'other'),
    received_at: now.toISOString(),
    raw_text,
    submitted_by: 'n8n form',
  },
};

// Node: "Load Sample Intakes" — Code node, mode: Run Once for All Items
// Emits one item per synthetic intake. The samples below are inlined from ../samples/ by scripts/build-workflow.js.
// To run a single intake (e.g. for the Loom failure demo) set ONLY = 'intake-3'.

const ONLY = null; // null = all three | 'intake-1' | 'intake-2' | 'intake-3'

const SAMPLES = [
  {
    "intake_id": "intake-1",
    "channel": "voicemail",
